import {createNavigation} from "./navigation.mjs";
/** Personal publishing prototype. All content, prices, orders and AI replies are examples; no external writes or credential collection. */
const main=document.querySelector('#main');
const articles=[{id:'small',category:'独立实践',title:'一个人的项目，先做小，再做长。',desc:'从一个具体的问题开始，而不是从一套庞大的系统开始。',time:'6 分钟',code:'SMALL / LONG'},{id:'agent',category:'技术与 AI',title:'做一个可靠的 Agent，先给它清楚的边界',desc:'哪些交给模型判断，哪些应该交给程序。',time:'8 分钟',code:'BUILD / TRUST'},{id:'life',category:'生活与认知',title:'给生活留一点没有产出的时间',desc:'不是每一件值得做的事，都需要变成待办。',time:'4 分钟',code:'LIFE / SPACE'},{id:'value',category:'商业与赚钱',title:'有人愿意付钱，和有人说喜欢，是两回事',desc:'从真实的需求、交付和反馈，理解一个小生意。',time:'7 分钟',code:'VALUE / PRICE'}];
const products=[{id:'website',name:'个人网站搭建手册',cover:'一个人的<br>网站',en:'BUILD YOUR OWN PLACE',desc:'从定位、内容到上线的完整工作底稿。',price:99,term:'365 天阅读',kind:'实践手册',sections:['先定义网站的用途','组织内容与设计页面','上线前检查与持续维护']},{id:'business',name:'独立项目验证笔记',cover:'从想法<br>到第一单',en:'IDEA TO FIRST CUSTOMER',desc:'把需求、定价与交付想清楚，再投入时间。',price:129,term:'365 天阅读',kind:'专题笔记',sections:['把想法改写成具体问题','验证需求与设计最小交付','定价、沟通与复盘']},{id:'review',name:'个人复盘工作手册',cover:'把日子<br>过明白',en:'NOTES FOR A BETTER LIFE',desc:'给选择、行动与长期思考留一个位置。',price:49,term:'365 天阅读',kind:'思考模板',sections:['记录一周的真实状态','辨认重要与紧急','把复盘变成下一步行动']}];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const row=a=>`<a class="article-row" href="#/article/${a.id}"><span class="category">${a.category}</span><div><h3>${a.title}</h3><p>${a.desc}</p></div><span class="row-meta">${a.time} ↗</span></a>`;
const cover=p=>`<div class="product-cover"><div class="book"><small>LINGBO / ${p.kind}</small><strong>${p.cover}</strong><small>${p.en}</small></div></div>`;
const card=p=>`<a class="product-card" href="#/product/${p.id}">${cover(p)}<div class="product-info"><h3>${p.name}</h3><p>${p.desc}</p><div class="price-row"><span class="price">¥${p.price}<small>示例价</small></span><span class="quiet">查看内容 ↗</span></div></div></a>`;
function home(){return `<section class="hero"><div><span class="eyebrow">你好，我是黄凌波。</span><h1>关于技术、生活，<br>和<span>自己的可能。</span></h1><p>这里放着我的文字、作品和实践。<br>聊技术，也聊选择；关心如何把想法做出来，<br>也关心怎样过好自己的生活。</p><div class="hero-links"><a class="text-link" href="#/writing">从一篇文章开始 ↗</a><a class="text-link" href="#/about">多认识我一点</a></div></div><a class="feature" href="#/article/small"><div class="feature-top"><span>本期选读 / 独立实践</span><span class="label">示例文章</span></div><h2>一个人的项目，<br>先做小，<br>再做长。</h2><span class="feature-mark" aria-hidden="true">&</span><div class="feature-bottom"><span>想法之后，是具体的行动。</span><span>阅读 ↗</span></div></a></section><section class="writing-home"><div class="section-head"><div><h2>最近的文字</h2><p>技术之外，还有生活里的问题。</p></div><a class="text-link" href="#/writing">全部文章 ↗</a></div>${articles.slice(1).map(row).join('')}</section><section class="shop-section"><div class="section-head"><div><h2>把经验整理成作品。</h2><p>小店里的手册与专题，先看内容，再决定是否适合你。</p></div><a class="text-link" href="#/shop">逛逛小店 ↗</a></div><div class="products">${products.map(card).join('')}</div></section><section class="home-end"><div><h2>文字之外，也在动手。</h2><p>一些工具、实验，以及还在生长的想法。</p></div><a class="button secondary" href="#/projects">看看作品 ↗</a></section>`}
const state={category:'全部',search:'',messages:[],question:'',adminTab:'orders',proposal:null,savedDraft:'',draft:'',orders:[{id:'DEMO-001',buyer:'示例买家 A',product:'个人网站搭建手册',amount:99,status:'待开通',term:'待实际开通后起算'},{id:'DEMO-002',buyer:'示例买家 B',product:'独立项目验证笔记',amount:129,status:'待撤权',term:'示例权益已到期'},{id:'DEMO-003',buyer:'示例买家 C',product:'个人复盘工作手册',amount:49,status:'已交付',term:'示例有效期内'}]};
let navigation,toastTimer,answerTimer;
const titleNames={home:'首页',writing:'文字',shop:'小店',article:'文章',product:'商品详情',projects:'作品',about:'关于',social:'社媒',chat:'对话',admin:'工作台'};
function back(fallback='home'){const prev=navigation?.previous();return `<button class="back" data-back="${fallback}">← 返回${titleNames[(prev||fallback).split('/')[0]]||'上一页'}</button>`}
function pageHead(title,subtitle='',fallback='home'){return `<div class="page-head">${back(fallback)}<h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>`}
function writing(){return `${pageHead('文字与想法','技术、生活、独立实践。选一个关心的话题，慢慢读。')}<div class="filterbar" aria-label="文章分类">${['全部','技术与 AI','生活与认知','独立实践','商业与赚钱'].map(c=>`<button data-category="${c}" class="${state.category===c?'active':''}" aria-pressed="${state.category===c}">${c}</button>`).join('')}</div><input class="search-field" id="article-search" aria-label="搜索文章" placeholder="搜索标题或关键词" value="${esc(state.search)}"><div id="article-results">${filteredArticles()}</div><p class="sample-note">本页文字为设计示例，不代表已发表的真实个人内容。</p>`}
function filteredArticles(){const list=articles.filter(a=>(state.category==='全部'||a.category===state.category)&&`${a.title}${a.desc}`.includes(state.search.trim()));return list.length?list.map(row).join(''):'<div class="empty">没有找到相应文章。试试其他关键词，或切换到“全部”。</div>'}
const bodies={
 small:[['把问题缩小到一个人','一个项目最容易变复杂的时候，往往是还没有人真正使用它的时候。界面可以不断补充，功能清单可以无限延长，但这些并不能替代一个明确的问题。','先写下：谁在什么场景遇到什么困难？如果连一个具体的人都想不出来，先不要急着增加功能。'],['交付一个小而完整的结果','“小”不是做一半，而是把承诺缩小。一个能让人读完、理解、用起来的结果，比十个只有入口的功能更有价值。','先让一位使用者走完整条路径：发现内容、判断是否适合、获得交付、提出反馈。每一步都值得亲自走一遍。'],['让下一步来自真实反馈','有人愿意回来，说明这件事可能值得继续。有人愿意付费，意味着你还需要把交付、维护和沟通做好。','不要把一时热情当成长期承诺。留下足够小的维护负担，才有机会把一个项目做长。']],
 agent:[['先分清判断与执行','让模型理解需求，让程序核对权限。阅读一段文章需要理解，确认账户是否有权限则需要确定的规则。','如果两件事交给同一个自由发挥的流程，错误就很难定位。'],['一次确认，对应一次具体变更','站长看到的应是目标、原文、新文和影响范围，而不只是“我准备优化一下”。','内容版本改变后，旧确认应失效。重复点击也只能执行一次。'],['失败也要有清晰出口','不要把没收到响应当成没有执行。先查看操作结果，再决定是否重试。','清楚的边界不是限制能力，而是让使用者知道什么时候可以相信结果。']],
 life:[['日程之外，还有感受','散步、闲聊和发呆，不一定都要带回一个结论。总想着把每段时间变成产出，会让人忽略自己真正喜欢什么。','给一天留一段没有指标的时间。它不需要漂亮的复盘，也不需要公开展示。'],['区分想做与应该做','很多待办并不是自己的愿望，而是看见别人正在做。停下来问一句：如果没有人知道，我还想不想继续？','答案未必立刻出现，但这个问题能让选择诚实一点。'],['慢一点也能往前走','长期方向可以清楚，日常节奏却不必永远紧绷。允许生活有空白，不等于没有追求。','把恢复精力也当成生活的一部分，而不是完成全部任务之后才能领取的奖励。']],
 value:[['先确认对方真正需要什么','“这个想法不错”是一种反馈，但不一定是购买意愿。比称赞更具体的问题是：对方正在用什么方式解决，有多麻烦？','把介绍从功能名称改成可以交付的结果，讨论会更清楚。'],['价格里也包含交付','售卖的不只是一个链接。读者还需要知道内容范围、能看多久、何时交付，以及遇到问题怎样联系你。','小规模时，人工沟通有机会暴露这些问题；自动化则应该建立在已经走通的流程上。'],['不要把收益承诺当成价值','一份资料可以帮助理解和行动，但不能替每个人保证结果。说明适合谁、不适合谁，往往比夸张承诺更能建立信任。','这些是原型中的示例观点，并非真实营收案例或投资建议。']]};
function article(id,section){const a=articles.find(x=>x.id===id);if(!a)return missing();const parts=bodies[id];return `${pageHead(a.title,`${a.category} · ${a.time} · 示例文章`,'writing')}<div class="detail-grid"><article class="reading-body"><div class="article-cover"><span>${a.code}<br><small>文字 / 黄凌波的个人空间</small></span><b aria-hidden="true">${id==='small'?'&':id==='agent'?'{}':id==='life'?'…':'?'}</b></div><p>${a.desc}</p><blockquote>${id==='small'?'先做一个有人愿意使用的结果。':id==='agent'?'让能力有边界，让结果有来路。':id==='life'?'不必把所有时间，都证明给别人看。':'把价值和交付说清楚。'}</blockquote>${parts.map((p,i)=>`<section id="section-${i+1}"><h2>${p[0]}</h2><p>${p[1]}</p><p>${p[2]}</p></section>`).join('')}<p class="sample-note">本文为原型排版与交互示例，真实文章之后由站长提供。</p><a class="text-link" href="#/chat">围绕本站公开内容提问 ↗</a></article><aside class="toc"><span class="eyebrow">这篇文章</span>${parts.map((p,i)=>`<a href="#/article/${id}/section-${i+1}" data-section="section-${i+1}">${p[0]}</a>`).join('')}<div class="mini-panel"><strong>继续阅读</strong><a href="#/article/${articles[(articles.indexOf(a)+1)%articles.length].id}">${articles[(articles.indexOf(a)+1)%articles.length].title}</a></div>${id==='small'||id==='value'?'<a class="text-link" href="#/shop">相关手册与专题 ↗</a>':''}</aside></div>`}
function shop(){return `${pageHead('一些值得带走的东西。','把零散的思考，整理成可阅读、可使用的手册与专题。')}<div class="products">${products.map(card).join('')}</div><div class="home-end"><div><h2>先了解，再决定。</h2><p>查看目录与试读 → 加微信确认内容 → 付款后开通飞书阅读。<br>每晚集中处理订单，非即时发货。</p></div><span class="quiet">所有商品、价格与期限均为示例</span></div>`}
function product(id){const p=products.find(p=>p.id===id);if(!p)return missing();return `<div class="page-head">${back('shop')}</div><section class="product-detail">${cover(p)}<div class="product-summary"><span class="eyebrow">小店 / ${p.kind} · 示例商品</span><h1>${p.name}</h1><p class="quiet">${p.desc}</p><div class="price-row"><span class="price">¥${p.price}<small>示例价</small></span><span class="label">飞书阅读</span></div><div class="facts"><div><span>访问期限</span><strong>${p.term} · 示例</strong></div><div><span>交付方式</span><strong>指定飞书账号授权</strong></div><div><span>处理时间</span><strong>每晚集中处理</strong></div></div><button class="button" data-buy="${p.id}">加微信咨询购买 ↗</button><p class="sample-note">当前为设计预览，不接受付款，不提供真实交付链接。</p></div></section><div class="detail-grid"><article class="reading-body"><h2>你会读到什么</h2><p>这份${p.kind}把一个问题拆成可以逐步理解和实践的部分。下列目录与试读用于展示商品详情，实际内容和售卖规则待站长确认。</p><ol>${p.sections.map(s=>`<li>${s}</li>`).join('')}</ol><h2 id="sample">先读一小段</h2><blockquote>${p.id==='website'?'一个网站的起点，是知道你希望谁来、带走什么。':p.id==='business'?'先把一个具体的问题解决，再讨论规模。':'复盘不是对自己的审判，而是为了做出下一次选择。'}</blockquote><p>开始之前，先写下当前最想解决的问题。把你已经知道的、还需要验证的分开，选一个能够在这周完成的动作，再记录真实结果。</p><h2>适合与不适合</h2><p>适合愿意自己阅读和动手实践的人。不包含一对一服务，不保证收益，也不以模板替代个人判断。具体更新与答疑范围在正式售卖前明确。</p><h2>购买与阅读</h2><p>加微信时带上商品名称。确认内容、价格、访问期限和退款说明后再付款；核实到账后，为你指定的飞书账号开通阅读。访问期建议从实际开通起算。</p><p class="sample-note">原型中的目录、期限与规则均为方案演示，不构成当前可购买的服务。</p></article><aside class="toc"><strong>购买前想了解更多？</strong><p class="quiet">先看试读，再通过微信确认。不是自动发货，也不需要在网站填支付信息。</p><button class="button secondary" data-buy="${p.id}">查看联系与购买说明</button></aside></div>`}
function projects(){return `${pageHead('做过的尝试，正在长大的想法。','这里保留动手的痕迹。当前展示的是设计示例，真实项目之后补充。')}<div class="project-grid"><a href="#/project/website"><div class="project-visual"><span style="font:38px var(--serif);color:var(--blue)">文字、作品、一个小店。</span></div><div class="project-copy"><h2>个人空间</h2><p class="quiet">从展示交互，到认真承载内容与业务。设计中的项目。</p></div></a><a href="#/project/mars"><div class="project-visual"><img src="mars-panorama.png" alt="火星探索交互实验的岩石与远山"></div><div class="project-copy"><h2>火星漫游实验</h2><p class="quiet">一个可操作的 3D 交互实验。作为作品存在，不再挡在网站入口。</p></div></a></div>`}
function project(id){if(!['website','mars'].includes(id))return missing();const mars=id==='mars';return `${pageHead(mars?'火星漫游实验':'个人空间',mars?'交互实验 · 保留的原型作品':'个人网站 · 设计中的项目','projects')}<div class="detail-grid"><article class="reading-body">${mars?'<img src="mars-panorama.png" alt="火星场景全景" style="border-radius:8px">':'<div class="article-cover"><span>PERSONAL SPACE<br>从表达开始</span><b>H.</b></div>'}<h2>为什么做这件事</h2><p>${mars?'用移动、打造与归航，探索个人网站能够怎样被体验。它是一件可以玩的作品，不是阅读文章的前置任务。':'把文章、作品、社媒和商品放在一个属于自己的地方。让初次见面的读者理解这里在关注什么，也方便感兴趣的人继续联系。'}</p><h2>保留什么，改变什么</h2><p>${mars?'保留地形、角色动作和归航镜头。主站不再自动加载 3D，只在主动进入实验时加载。实验中的旧 Chat 和配置均是模拟，不代表新业务方案。':'用直接的内容导航替代复杂的进站流程。首页建立第一印象，文章积累信任，商品页解释价值，微信负责进一步沟通。'}</p><h2>当前状态</h2><p>这是可操作设计原型，不代表已经实现真实 AI、支付、权限或业务收益。</p>${mars?'<a class="button" href="explore.html#/scene">进入火星实验 ↗</a>':'<a class="button" href="#/shop">看看小店设计 ↗</a>'}</article><aside class="toc"><span class="eyebrow">项目说明</span><p class="quiet">设计原型 / 示例内容<br>未连接真实业务服务</p><a href="#/projects">查看全部作品</a></aside></div>`}
function about(){return `${pageHead('你好，我是黄凌波。','这里是一个可以慢慢认识我的地方。')}<div class="about-grid"><div class="initial-art" aria-hidden="true">凌</div><article class="reading-body"><h2>技术是一个起点，生活不止于此。</h2><p>这个空间想容纳的不只是技术文章，也有生活里的选择、独立实践和对商业的观察。</p><p>我希望一篇文字能带来一个有用的问题，一件作品能把想法往前推一步。比起堆满标签，这里更适合从具体内容开始认识一个人。</p><p class="sample-note">以上为个人定位文案提案。真实履历、头像和经历待本人补充，不编造任职、收入或成绩。</p><div class="hero-links"><a class="text-link" href="#/social">在别处找到我 ↗</a><a class="text-link" href="#/writing">读一篇文字</a></div></article></div>`}
function social(){return `${pageHead('在这些地方，保持联系。','账号信息由本人补充。未确认的渠道不会跳转到陌生主页。')}<div class="social-grid">${[['GitHub · 个人','Lingbo-Huang','https://github.com/Lingbo-Huang'],['GitHub · 工作','adu-works','https://github.com/adu-works'],['小红书','账号待补'],['抖音','账号待补'],['知乎','账号待补'],['Bilibili','账号待补'],['LinkedIn','账号待补'],['X','账号待补']].map(([name,handle,url])=>url?`<a class="social-card" href="${url}" target="_blank" rel="noopener noreferrer"><div>${name}<small>${handle}</small></div><span>↗</span></a>`:`<div class="social-card"><div>${name}<small>${handle}</small></div><span class="quiet">—</span></div>`).join('')}</div><div class="home-end"><div><h2>关于商品，直接聊。</h2><p>看过目录与试读后，可以通过微信进一步确认。</p></div><a class="button secondary" href="#/shop">前往小店</a></div>`}
function chat(){return `${pageHead('问问这里的内容','只使用本站公开内容的对话演示。不收集 API Key，不查询付费资料。')}<div class="chat-layout"><aside class="chat-sidebar"><button class="button secondary" data-action="new-chat">新建对话</button><p>本次访问的对话</p><span class="quiet">离开查看来源后可继续。<br>刷新会清空模拟会话。</span></aside><div class="chat-main"><div class="messages" aria-live="polite">${messages()}</div><form class="chat-input" id="chat-form"><textarea aria-label="你的问题" placeholder="问一个关于本站公开内容的问题…" maxlength="2000">${esc(state.question)}</textarea><button class="button" type="submit">发送</button></form><small class="sample-note">演示回答来自固定示例，不调用真实模型。</small></div></div>`}
function messages(){return state.messages.length?state.messages.map(m=>`<div class="message ${m.role}">${esc(m.text)}${m.source?` <a href="#/article/${m.source}/section-1">[来源：${articles.find(a=>a.id===m.source).title}]</a>`:''}</div>`).join(''):'<h2>从一个问题开始。</h2><p class="quiet">可以问：“一个人的项目，怎样开始？”<br>也可以直接阅读文章，形成自己的判断。</p>'}
function admin(){return `${pageHead('站长工作台','管理内容，也把每一笔交付记清楚。这里是公开可查看的模拟后台，请勿填写真实客户或付款信息。')}<div class="admin-layout"><aside class="admin-nav">${[['orders','订单与待办'],['customers','客户与权益'],['products','商品管理'],['content','内容与 Agent']].map(([id,label])=>`<button data-admin-tab="${id}" class="${state.adminTab===id?'active':''}">${label}</button>`).join('')}</aside><section class="admin-panel">${adminPanel()}</section></div>`}
function adminPanel(){if(state.adminTab==='orders')return `<div class="admin-stats"><div>待开通<strong>${state.orders.filter(o=>o.status==='待开通').length}</strong>已核实示例订单</div><div>待发送<strong>${state.orders.filter(o=>o.status==='待发送').length}</strong>权限已开通</div><div>到期待撤权<strong>${state.orders.filter(o=>o.status==='待撤权').length}</strong>需到飞书核查</div></div><div class="section-head"><h2>待办与订单</h2><button class="button secondary" data-action="new-order">登记模拟订单</button></div><div class="table-wrap"><table><thead><tr><th>订单 / 客户</th><th>商品 / 实收</th><th>交付与权限</th><th>下一步</th></tr></thead><tbody>${state.orders.map(o=>`<tr><td>${o.id}<br><span class="quiet">${esc(o.buyer)}</span></td><td>${esc(o.product)}<br>¥${o.amount} · 示例</td><td><span class="status ${o.status==='待撤权'?'warning':''}">${o.status}</span><br><small class="quiet">${o.term}</small></td><td>${['待开通','待发送','待撤权'].includes(o.status)?`<button data-order="${o.id}">${o.status==='待开通'?'记录已开通':o.status==='待发送'?'记录已发链接':'记录已撤权'}</button>`:'<span class="quiet">暂无待办</span>'}</td></tr>`).join('')}</tbody></table></div><p class="sample-note">这些按钮只改变本次演示记录，不会访问飞书、发送微信或核实真实付款。</p>`;
 if(state.adminTab==='customers')return `<h2>客户与权益 · 示例</h2><div class="table-wrap"><table><thead><tr><th>客户</th><th>所购内容</th><th>当前记录</th></tr></thead><tbody>${state.orders.map(o=>`<tr><td>${esc(o.buyer)}<br><small>飞书身份：模拟账号</small></td><td>${esc(o.product)}</td><td>${o.status}<br><small>${o.term}</small></td></tr>`).join('')}</tbody></table></div><div class="mini-panel">权益到期与实际撤权分开记录。处理撤权前，应核对续购和其他有效订单。</div>`;
 if(state.adminTab==='products')return `<h2>商品预览</h2><p class="quiet">商品均为示例，当前未开放真实售卖。</p>${products.map(p=>`<div class="article-row"><span class="category">${p.kind}</span><div><h3>${p.name}</h3><p>示例价 ¥${p.price} · ${p.term} · 飞书交付</p></div><a class="text-link" href="#/product/${p.id}">查看 ↗</a></div>`).join('')}<p class="sample-note">真实价格、联系信息与飞书资源映射，在正式后台实现后配置。</p>`;
 return `<h2>内容与 Agent · 演示</h2><p class="quiet">写下文章草稿或修改目标，先看差异，再决定是否保存。本次演示不发布网站内容。</p><form class="admin-form" id="draft-form"><label>草稿或修改目标<textarea id="draft-input" maxlength="4000" placeholder="例如：整理一篇关于个人项目的文章…">${esc(state.draft)}</textarea></label><div class="dialog-actions"><button class="button" type="submit">生成提案 · 模拟</button><button class="button secondary" type="button" data-action="save-draft">直接保存草稿 · 模拟</button></div></form><div id="proposal">${proposal()}</div>`}
function proposal(){if(!state.proposal)return state.savedDraft?`<div class="mini-panel">本次模拟草稿已保存：${esc(state.savedDraft)}</div>`:'';return `<div class="proposal"><span class="eyebrow">提案 / 仅修改模拟草稿</span><h3>先检查，再保存</h3><del>${esc(state.savedDraft||'暂无草稿')}</del><ins>${esc(state.proposal)}</ins><p class="quiet">影响：仅本次演示中的草稿，不发布、不操作飞书。</p><div class="dialog-actions"><button class="button" data-action="confirm-draft">确认保存 · 模拟</button><button class="button secondary" data-action="cancel-draft">取消</button></div></div>`}
function missing(){return `${pageHead('这页暂时没有内容。','链接可能已变更，可以返回上一页或继续浏览。')}<a class="button" href="#/home">前往首页</a>`}
function toast(text){const n=document.querySelector('#notice');n.textContent=text;n.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>n.classList.remove('show'),3000)}
const dialog=document.querySelector('#purchase-dialog');
function openDialog(content){dialog.innerHTML=`<div class="dialog-top"><span class="eyebrow">设计预览 / 模拟操作</span><button class="icon-button" data-action="close-dialog" aria-label="关闭弹窗">×</button></div>${content}`;dialog.showModal()}
function purchase(id){const p=products.find(p=>p.id===id);if(!p)return;openDialog(`<h2 id="dialog-title">先聊聊，再决定。</h2><p>${p.name} · ¥${p.price}（示例价）</p><p class="quiet">加微信时注明来意，确认内容、价格和访问期限后再付款。每晚集中处理订单，非即时发货。</p><div class="contact-placeholder"><strong>微信号与联系二维码待本人提供</strong><span>原型不收款，也不生成虚假二维码。</span></div><p>购买备注：<strong>购买：${p.name} / ${p.id.toUpperCase()}</strong></p><div class="dialog-actions"><button class="button" data-copy-product="${p.id}">复制购买备注</button><button class="button secondary" disabled>微信号待补充</button></div><p class="sample-note">实际交付需提供用于阅读的飞书账号，核实到账后按账号开通。不要在本原型提供真实付款或账号信息。</p>`)}
function orderDialog(id){const o=state.orders.find(o=>o.id===id);if(!o)return;const next={'待开通':'待发送','待发送':'已交付','待撤权':'已撤权'}[o.status];if(!next)return;openDialog(`<h2 id="dialog-title">确认记录${next==='待发送'?'已开通':next==='已交付'?'已发送链接':'已撤权'}？</h2><p>${esc(o.buyer)} · ${esc(o.product)}</p><p class="quiet">这只更新模拟后台记录，实际飞书操作需要另行完成。${next==='已撤权'?'正式使用时应先核对续购与其他有效权益。':''}</p><button class="button" data-confirm-order="${o.id}" data-expected="${o.status}">确认记录 · 模拟</button>`)}
function readView(){return {scroll:scrollY,category:state.category,search:state.search}}
function render(route='home',view){if(dialog.open)dialog.close();if(view){state.category=view.category??state.category;state.search=view.search??state.search}let [page,id,section]=route.split('/');if(page==='scene'){location.replace('explore.html#/scene');return}if(page==='articles')page='writing';const renders={home,writing,shop,about,social,projects,chat,admin,contact:social};main.innerHTML=page==='article'?article(id,section):page==='product'?product(id):page==='project'?project(id):(renders[page]||missing)();document.title=`${page==='article'?articles.find(a=>a.id===id)?.title||'文章':page==='product'?products.find(p=>p.id===id)?.name||'商品':titleNames[page]||'个人空间'} · 黄凌波`;document.querySelectorAll('nav a').forEach(a=>{const active=a.hash===`#/${page==='article'?'writing':page==='product'?'shop':page==='project'?'projects':page}`;if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});requestAnimationFrame(()=>{if(section){const target=document.getElementById(section);target?.classList.add('section-focus');target?.scrollIntoView();}else window.scrollTo(0,view?.scroll||0)})}
if(!location.hash||location.hash==='#main')history.replaceState(null,'','#/home');
navigation=createNavigation(window,readView,render);navigation.start();
document.addEventListener('click',async e=>{if(e.target.closest('a[href="#main"]')){e.preventDefault();main.focus();main.scrollIntoView();return}const section=e.target.closest('[data-section]');if(section){e.preventDefault();document.getElementById(section.dataset.section)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return}const link=e.target.closest('a[href^="#/"]');if(link&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&!e.altKey&&e.button===0){e.preventDefault();navigation.go(link.hash.slice(2));return}const b=e.target.closest('button');if(!b)return;if(b.dataset.back){navigation.back(b.dataset.back);return}if(b.dataset.category){state.category=b.dataset.category;main.innerHTML=writing();document.querySelector(`[data-category="${state.category}"]`)?.focus();return}if(b.dataset.buy){purchase(b.dataset.buy);return}if(b.dataset.adminTab){state.adminTab=b.dataset.adminTab;main.innerHTML=admin();return}if(b.dataset.order){orderDialog(b.dataset.order);return}if(b.dataset.confirmOrder){const o=state.orders.find(o=>o.id===b.dataset.confirmOrder);if(!o||o.status!==b.dataset.expected){toast('记录已经变化，请重新核对。');dialog.close();return}o.status={'待开通':'待发送','待发送':'已交付','待撤权':'已撤权'}[o.status];if(o.status==='待发送')o.term='本次模拟开通起 365 天';dialog.close();main.innerHTML=admin();toast('模拟记录已更新，未执行外部操作。');return}if(b.dataset.copyProduct){const p=products.find(p=>p.id===b.dataset.copyProduct);try{await navigator.clipboard.writeText(`购买：${p.name} / ${p.id.toUpperCase()}`);toast('购买备注已复制；当前商品仅为示例。')}catch{toast('无法自动复制，请手动选取弹窗中的购买备注。')}return}
 switch(b.dataset.action){case'close-dialog':dialog.close();break;case'new-chat':state.messages=[];state.question='';clearTimeout(answerTimer);main.innerHTML=chat();break;case'new-order':openDialog(`<h2 id="dialog-title">登记模拟订单</h2><p class="quiet">请勿填写真实个人信息；只用于体验记录流程。</p><form class="admin-form" id="order-form"><label>示例客户<input name="buyer" required maxlength="30" value="示例买家 D"></label><label>商品<select name="product">${products.map(p=>`<option value="${p.id}">${p.name} · ¥${p.price} 示例价</option>`).join('')}</select></label><p class="sample-note">模拟已人工核实到账。正式后台需核对真实收款，不能据此视为付款成功。</p><button class="button">保存模拟订单</button></form>`);break;case'save-draft':if(!state.draft.trim()){toast('先写下一些内容。');break}state.savedDraft=state.draft;state.proposal=null;main.innerHTML=admin();toast('模拟草稿已保存，未发布。');break;case'confirm-draft':if(!state.proposal)break;state.savedDraft=state.proposal;state.proposal=null;main.innerHTML=admin();toast('已确认保存模拟草稿。');break;case'cancel-draft':state.proposal=null;document.querySelector('#proposal').innerHTML=proposal();toast('提案已取消，没有保存变更。');break}});
document.addEventListener('input',e=>{if(e.target.id==='article-search'){state.search=e.target.value;document.querySelector('#article-results').innerHTML=filteredArticles()}if(e.target.id==='draft-input')state.draft=e.target.value;if(e.target.closest('#chat-form'))state.question=e.target.value});
document.addEventListener('submit',e=>{if(e.target.id==='chat-form'){e.preventDefault();const q=state.question.trim();if(!q)return;state.messages.push({role:'user',text:q});state.question='';const source=/赚钱|付钱|商业|价格/.test(q)?'value':/生活|时间|复盘/.test(q)?'life':/agent|边界|模型/i.test(q)?'agent':/项目|开始|网站/.test(q)?'small':null;state.messages.push(source?{role:'assistant',text:`演示回答：${bodies[source][0][1]} 可以查看原文进一步核对。`,source}:{role:'assistant',text:'本站示例材料还没有提供这部分信息。你可以询问个人项目、Agent 边界、生活节奏或商业交付；付费内容不在问答范围内。'});main.innerHTML=chat();document.querySelector('#chat-form textarea').focus();return}if(e.target.id==='draft-form'){e.preventDefault();if(!state.draft.trim()){toast('先写下草稿或修改目标。');return}state.proposal=state.draft.trim()+'\n\n[模拟整理建议] 补充具体问题、行动步骤和可核查依据。';document.querySelector('#proposal').innerHTML=proposal();return}if(e.target.id==='order-form'){e.preventDefault();const f=new FormData(e.target);const p=products.find(p=>p.id===f.get('product'));state.orders.push({id:'DEMO-'+String(state.orders.length+1).padStart(3,'0'),buyer:String(f.get('buyer')).slice(0,30),product:p.name,amount:p.price,status:'待开通',term:'待实际开通后起算'});dialog.close();main.innerHTML=admin();toast('模拟订单已登记，刷新后清空。')}});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
